const tabId = 1962625065;

const articles = await browserjs(tabId, () => {
  // Let's find all article elements or links in main
  const main = document.querySelector('main');
  if (!main) return [];

  const links = Array.from(main.querySelectorAll('a'));
  const results = [];
  const seenUrls = new Set();

  for (const a of links) {
    const href = a.href;
    if (!href || seenUrls.has(href)) continue;
    if (href.includes('/news/climate') || href.includes('/news/')) {
      const text = a.innerText.trim();
      if (text && text.length > 5 && !text.toLowerCase().includes('see more')) {
        seenUrls.add(href);
        results.push({
          text,
          href
        });
      }
    }
  }
  return results;
});

console.log("Found articles:", JSON.stringify(articles, null, 2));

